--
-- Table structure for table `message`
--

DROP TABLE IF EXISTS `message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `conversation_id` bigint unsigned NOT NULL COMMENT '鎵?睘浼氳瘽',
  `sender_id` bigint unsigned NOT NULL COMMENT '鍙戦?鑰',
  `receiver_id` bigint unsigned NOT NULL COMMENT '鎺ユ敹鑰',
  `content` varchar(1000) NOT NULL COMMENT '娑堟伅鍐呭?',
  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '鏄?惁宸茶? 0鏈?? 1宸茶?',
  `read_time` datetime(3) DEFAULT NULL COMMENT '宸茶?鏃堕棿',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎锛堟挙鍥烇紝棰勭暀锛',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_conv_id` (`conversation_id`,`id` DESC),
  KEY `idx_receiver_read` (`receiver_id`,`is_read`)
) ENGINE=InnoDB AUTO_INCREMENT=199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='绉佷俊娑堟伅琛';
/*!40101 SET character_set_client = @saved_cs_client */;

