INSERT INTO `message` VALUES (1,1,2,3,'在吗？想请教你一个问题。',1,'2026-09-14 06:18:01.548',0,'2026-09-14 04:18:01.548','2026-09-14 16:18:01.575'),(2,1,3,2,'在的，你说。',1,'2026-09-14 05:18:01.548',0,'2026-09-14 05:18:01.548','2026-09-14 16:18:01.575'),(3,1,2,3,'MySQL 的分页查询有没有推荐写法？',1,'2026-09-14 06:18:01.548',0,'2026-09-14 06:18:01.548','2026-09-14 16:18:01.575'),(4,1,3,2,'ORDER BY 带上主键，然后限制 size。',1,'2026-09-14 07:18:01.548',0,'2026-09-14 07:18:01.548','2026-09-14 16:18:01.575'),(5,1,2,3,'为什么必须带主键？',1,'2026-09-14 08:18:01.548',0,'2026-09-14 08:18:01.548','2026-09-14 16:18:01.575'),(6,1,3,2,'因为 create_time 可能重复，排序不稳定。',1,'2026-09-14 09:18:01.548',0,'2026-09-14 09:18:01.548','2026-09-14 16:18:01.575'),(7,1,2,3,'明白了，谢谢！',1,'2026-09-14 10:18:01.548',0,'2026-09-14 10:18:01.548','2026-09-14 16:18:01.575'),(8,1,3,2,'不客气。',1,'2026-09-14 11:18:01.548',0,'2026-09-14 11:18:01.548','2026-09-14 16:18:01.575'),(9,1,3,2,'对了，周末有空吗？想约你一起看展。',1,'2026-09-14 16:18:10.146',0,'2026-09-14 13:18:01.548','2026-09-14 16:18:10.147'),(10,1,3,2,'好的，那就这么定了。',1,'2026-09-14 16:18:10.146',0,'2026-09-14 14:18:01.548','2026-09-14 16:18:10.147'),(11,5,7,5,'这是会话 5 的第 1 条测试消息。',1,'2026-09-14 10:18:01.548',0,'2026-09-11 22:18:01.548','2026-09-14 16:18:01.577'),(12,4,6,4,'这是会话 4 的第 1 条测试消息。',1,'2026-09-14 11:18:01.548',0,'2026-09-12 10:18:01.548','2026-09-14 16:18:01.577'),(13,3,5,3,'这是会话 3 的第 1 条测试消息。',1,'2026-09-14 12:18:01.548',0,'2026-09-12 22:18:01.548','2026-09-14 16:18:01.577'),(14,2,4,2,'这是会话 2 的第 1 条测试消息。',1,'2026-09-14 13:18:01.548',0,'2026-09-13 10:18:01.548','2026-09-14 16:18:01.577'),(15,5,5,7,'这是会话 5 的第 2 条测试消息。',1,'2026-09-14 09:18:01.548',0,'2026-09-11 16:18:01.548','2026-09-14 16:18:01.577'),(16,4,4,6,'这是会话 4 的第 2 条测试消息。',1,'2026-09-14 10:18:01.548',0,'2026-09-12 04:18:01.548','2026-09-14 16:18:01.577'),(17,3,3,5,'这是会话 3 的第 2 条测试消息。',1,'2026-09-14 11:18:01.548',0,'2026-09-12 16:18:01.548','2026-09-14 16:18:01.577'),(18,2,2,4,'这是会话 2 的第 2 条测试消息。',1,'2026-09-14 12:18:01.548',0,'2026-09-13 04:18:01.548','