--
-- Table structure for table `post`
--

DROP TABLE IF EXISTS `post`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `post` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `user_id` bigint unsigned NOT NULL COMMENT '浣滆?',
  `content` varchar(1000) NOT NULL DEFAULT '' COMMENT '鏂囨湰鍐呭?',
  `like_count` int unsigned NOT NULL DEFAULT '0' COMMENT '鐐硅禐鏁帮紙鍐椾綑锛',
  `comment_count` int unsigned NOT NULL DEFAULT '0' COMMENT '璇勮?鏁帮紙鍐椾綑锛',
  `image_count` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '鍥剧墖鏁?0~9',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_user_time` (`user_id`,`deleted`,`create_time` DESC),
  KEY `idx_time` (`deleted`,`create_time` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=172 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='鍔ㄦ?琛';
/*!40101 SET character_set_client = @saved_cs_client */;

