DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `username` varchar(32) NOT NULL COMMENT '鐧诲綍鍚嶏紝鍞?竴',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 鍝堝笇锛岀?姝㈡槑鏂',
  `nickname` varchar(32) NOT NULL COMMENT '鏄电О',
  `email` varchar(64) NOT NULL COMMENT '閭??锛屽敮涓',
  `gender` tinyint NOT NULL DEFAULT '0' COMMENT '鎬у埆 0鏈?煡 1鐢?2濂',
  `birthday` date DEFAULT NULL COMMENT '鐢熸棩',
  `bio` varchar(255) NOT NULL DEFAULT '' COMMENT '涓?汉绠?粙',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT '澶村儚 URL',
  `role` tinyint NOT NULL DEFAULT '1' COMMENT '瑙掕壊 1=USER 2=ADMIN',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '鐘舵? 1姝ｅ父 0绂佺敤',
  `following_count` int unsigned NOT NULL DEFAULT '0' COMMENT '鍏虫敞鏁帮紙鍐椾綑锛',
  `follower_count` int unsigned NOT NULL DEFAULT '0' COMMENT '绮変笣鏁帮紙鍐椾綑锛',
  `post_count` int unsigned NOT NULL DEFAULT '0' COMMENT '鍔ㄦ?鏁帮紙鍐椾綑锛',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎 0姝ｅ父 1宸插垹闄',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  UNIQUE KEY `uk_email` (`email`),
  KEY `idx_nickname` (`nickname`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=690 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='鐢ㄦ埛琛';
